WITH matched_keys AS (SELECT device, id FROM sessions EXCEPT SELECT device, id FROM sessions WHERE customer_id IS NULL), verified AS (SELECT s.* FROM sessions s INNER JOIN matched_keys k ON s.device = k.device AND s.id = k.id) SELECT DATE_TRUNC('YEAR', started_at) AS year_start, MIN(started_at) AS first_started_at, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, MAX(started_at) AS last_started_at, COUNT(*) FILTER (WHERE country = 'TH') AS th_rows, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, COUNT(CASE WHEN country = 'UK' THEN 1 END) AS uk_count FROM verified GROUP BY DATE_TRUNC('YEAR', started_at)
